const int LEFT_SENSOR = 2;
const int RIGHT_SENSOR = 3;
const int BUMPER_PIN = 4;

void setup() {
  pinMode(LEFT_SENSOR, INPUT);
  pinMode(RIGHT_SENSOR, INPUT);
  pinMode(BUMPER_PIN, INPUT_PULLUP);
  pinMode(5, OUTPUT); pinMode(6, OUTPUT);
  pinMode(9, OUTPUT); pinMode(10, OUTPUT);
}

void driveForward() {
  digitalWrite(5, HIGH); digitalWrite(6, LOW);
  digitalWrite(9, HIGH); digitalWrite(10, LOW);
}
void turnLeft() {
  digitalWrite(5, LOW); digitalWrite(6, LOW);
  digitalWrite(9, HIGH); digitalWrite(10, LOW);
}
void turnRight() {
  digitalWrite(5, HIGH); digitalWrite(6, LOW);
  digitalWrite(9, LOW); digitalWrite(10, LOW);
}
void stopMotors() {
  digitalWrite(5, LOW); digitalWrite(6, LOW);
  digitalWrite(9, LOW); digitalWrite(10, LOW);
}

void loop() {
  if (digitalRead(BUMPER_PIN) == LOW) {
    stopMotors(); return;
  }
  int left = digitalRead(LEFT_SENSOR);
  int right = digitalRead(RIGHT_SENSOR);
  if (left == HIGH && right == HIGH) driveForward();
  else if (left == LOW && right == HIGH) turnLeft();
  else if (left == HIGH && right == LOW) turnRight();
  else stopMotors();
}
